import{_ as t,o as a,c as o,ae as n}from"./chunks/framework.Czhw_PXq.js";const g=JSON.parse('{"title":"ADR 033: Authentication Error Handling and Caching Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"adr/033-auth-error-handling.md","filePath":"adr/033-auth-error-handling.md"}'),i={name:"adr/033-auth-error-handling.md"};function r(s,e,c,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-033-authentication-error-handling-and-caching-strategy" tabindex="-1">ADR 033: Authentication Error Handling and Caching Strategy <a class="header-anchor" href="#adr-033-authentication-error-handling-and-caching-strategy" aria-label="Permalink to &quot;ADR 033: Authentication Error Handling and Caching Strategy&quot;">​</a></h1><p>Date: 2026-03-04</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>We encountered an issue where users were receiving <code>401 Unauthorized</code> errors when attempting to upload documents or fetch history, despite appearing to be logged in on the frontend. Investigation revealed that the browser was likely caching the <code>GET /api/auth/me</code> response, leading the frontend context to believe the session was valid when the underlying cookie had actually expired or was missing (e.g., waiting for the server to wake up).</p><p>Additionally, the frontend handled API errors generically, often masking the specific <code>401</code> status code, which prevented specific recovery actions (like auto-logout).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We have decided to implement a strict &quot;No-Store&quot; caching policy for authentication checks and a robust client-side error handling strategy for <code>401</code> responses.</p><h3 id="_1-cache-control-headers" tabindex="-1">1. Cache-Control Headers <a class="header-anchor" href="#_1-cache-control-headers" aria-label="Permalink to &quot;1. Cache-Control Headers&quot;">​</a></h3><p>We explicitly disable caching for all authentication-sensitive endpoints (<code>/me</code>, <code>/history</code>, <code>/analyze</code>).</p><ul><li><strong>Header</strong>: <code>Cache-Control: no-store, no-cache, must-revalidate, proxy-revalidate</code></li><li><strong>Rationale</strong>: This forces the browser to validate the session with the backend on every request/page load, ensuring the frontend state matches the backend session state.</li></ul><h3 id="_2-client-side-401-handling" tabindex="-1">2. Client-Side 401 Handling <a class="header-anchor" href="#_2-client-side-401-handling" aria-label="Permalink to &quot;2. Client-Side 401 Handling&quot;">​</a></h3><p>We implemented a dedicated <code>ApiError</code> class in the frontend to capture HTTP status codes.</p><ul><li><strong>Interceptor</strong>: API wrapper functions (<code>uploadTender</code>, <code>fetchHistory</code>) now catch non-2xx responses and throw <code>ApiError</code>.</li><li><strong>Auto-Logout</strong>: Critical components (like <code>Dashboard.tsx</code>) specifically catch <code>ApiError</code> with status <code>401</code> and trigger an immediate <code>handleLogout()</code>.</li><li><strong>Rationale</strong>: This prevents the application from entering a &quot;zombie&quot; state where the UI shows a logged-in user but API calls fail. Redirecting to login allows the user to re-authenticate and restore a valid session.</li></ul><h3 id="_3-cookie-path" tabindex="-1">3. Cookie Path <a class="header-anchor" href="#_3-cookie-path" aria-label="Permalink to &quot;3. Cookie Path&quot;">​</a></h3><p>We explicitly set the cookie <code>path</code> to <code>/</code> in the backend <code>AuthController</code>.</p><ul><li><strong>Rationale</strong>: Ensures the authentication cookie is sent for all routes, preventing issues where a cookie might be scoped too narrowly (e.g., set on <code>/api/auth</code> but not sent for <code>/api/tenders</code>).</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li><strong>Reliability</strong>: Authentication state is now strictly synchronized between frontend and backend.</li><li><strong>UX Recovery</strong>: Users are immediately guided to fix their session (login) rather than facing confusing errors.</li><li><strong>Security</strong>: Prevents stale sensitive data from hanging around in browser caches.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li><strong>Performance</strong>: Slight increase in network traffic as auth checks are never cached (though these are small JSON payloads).</li><li><strong>Strictness</strong>: Users may be logged out more aggressively if their session genuinely expires, rather than seeing a cached &quot;logged in&quot; view. This is considered a feature, not a bug.</li></ul>',23)])])}const p=t(i,[["render",r]]);export{g as __pageData,p as default};
